<script setup lang="ts">
import { computed, ref } from 'vue'
import { ChevronLeft, ChevronRight } from '@lucide/vue'
import { useAppStore } from '@/stores/app'
const store=useAppStore();const cursor=ref(new Date());const monthLabel=computed(()=>cursor.value.toLocaleString('en',{month:'long',year:'numeric'}));const days=computed(()=>{const year=cursor.value.getFullYear(),month=cursor.value.getMonth(),first=new Date(year,month,1),count=new Date(year,month+1,0).getDate();return [...Array((first.getDay()+6)%7).fill(null),...Array.from({length:count},(_,i)=>i+1)]});const workoutsFor=(day:number)=>store.history.filter(w=>{const d=new Date(w.startedAt);return d.getFullYear()===cursor.value.getFullYear()&&d.getMonth()===cursor.value.getMonth()&&d.getDate()===day});function shift(by:number){cursor.value=new Date(cursor.value.getFullYear(),cursor.value.getMonth()+by,1)}
</script>
<template><div class="page"><header class="page-head"><div><span class="eyebrow">TRAINING RHYTHM</span><h1>Calendar</h1><p>See consistency at a glance.</p></div></header><section class="calendar-panel"><header><button class="icon-button" @click="shift(-1)"><ChevronLeft/></button><h2>{{ monthLabel }}</h2><button class="icon-button" @click="shift(1)"><ChevronRight/></button></header><div class="calendar-week"><span v-for="day in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day">{{ day }}</span></div><div class="calendar-grid"><div v-for="(day,index) in days" :key="index" class="calendar-day" :class="{blank:!day,trained:day&&workoutsFor(day).length}"><template v-if="day"><span>{{ day }}</span><RouterLink v-for="workout in workoutsFor(day)" :key="workout.id" :to="`/history/${workout.id}`">{{ workout.title }}</RouterLink></template></div></div></section></div></template>
